std::vector<std::string> list_names() {
    std::vector<std::string> out;
    out.reserve(kEntriesCount);
    for (std::size_t i = 0; i < kEntriesCount; ++i) {
        out.emplace_back(kEntries[i].name);
    }
    return out;
}

const char* get(const std::string& name) {
    for (std::size_t i = 0; i < kEntriesCount; ++i) {
        if (name == kEntries[i].name) return kEntries[i].content;
    }
    return nullptr;
}

